import{_ as i,c as s,o as a,a5 as t}from"./chunks/framework.BLFC1wTn.js";const E=JSON.parse('{"title":"算法小记","description":"","frontmatter":{},"headers":[],"relativePath":"pages/interview/coding/learnMark/index.md","filePath":"pages/interview/coding/learnMark/index.md","lastUpdated":1763602731000}'),e={name:"pages/interview/coding/learnMark/index.md"},l=t('<h1 id="算法小记" tabindex="-1">算法小记 <a class="header-anchor" href="#算法小记" aria-label="Permalink to &quot;算法小记&quot;">​</a></h1><h2 id="数组" tabindex="-1">数组 <a class="header-anchor" href="#数组" aria-label="Permalink to &quot;数组&quot;">​</a></h2><p>数组是一种线性表结构，它用一组连续的内存空间，来存储一组具有相同类型的数据<br><strong>1.线性表</strong></p><ol><li>线性表，每个线性表上的数据最多只有前和后两个方向，数组、链表、队列、栈都是线性表结构；</li><li>非线性表，不是简单的前后关系，二叉树、堆、图等；</li><li>数组需要提前确定大小，在java里面可以使用ArrayList进行动态扩容</li></ol><p><strong>2.连续的内存空间和相同类型的数据</strong></p><ol><li>高效的访问元素，低效的删除、插入数据；</li><li>需要访问某个元素时，通过内存地址来访问，比如</li></ol><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a[i]_address </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> base_address </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> data_type_size</span></span></code></pre></div><ol start="3"><li>数组中最好是插入末尾O(1),最坏是插入头部O(n),插入第二个需要移动n-1个元素，插入第二个需要移动n-2个元素，(n+n-1+n-2+...+1)/n = (n+1)/2 = O(n),所以平均时间复杂度是O(n)</li><li>数组中删除头部O(n),删除末尾O(1),删除中间O(n),所以平均时间复杂度是O(n)</li></ol><p><strong>为什么数组下标为0</strong> 如果是从1开始计数，那么计算内存地址就会变为⬇️，每次访问数组都会多一次减法运算</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a[i]_address </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> base_address </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (i</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> data_type_size</span></span></code></pre></div><h2 id="链表" tabindex="-1">链表 <a class="header-anchor" href="#链表" aria-label="Permalink to &quot;链表&quot;">​</a></h2><p>链表不需要连续的内存空间，它通过指针将一组零散的内存块串联起来使用，常见的链表结构：</p><ol><li>单向链表</li><li>双向链表</li><li>循环链表</li></ol><p><strong>特点</strong></p><ol><li>链表的插入和删除非常高效，因为不需要保持内存的连续性，时间复杂度为O(1)</li><li>链表的查询时间复杂度为O(n)</li><li>双向链表因为有前驱指针，所以查询的时间复杂度为O(1)，但是会比单链表多存储一个指针；</li><li>对链表进行频繁的删除、插入操作还会导致频繁的内存申请和释放，容易造成内存碎片；</li></ol>',15),n=[l];function h(p,r,d,o,k,c){return a(),s("div",null,n)}const _=i(e,[["render",h]]);export{E as __pageData,_ as default};
